args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-11-06-p53-tad-dynamics');D<-file.path(P,'results/plot_data/p53_tad_dynamics_20261106');library(ggplot2);library(grid);source(file.path(P,'biofigure/scripts/figure_style.R'));font<-bf_font('Arial');cowplot::set_null_device('agg')
times<-c('0h','1h','4h','7h','10h','24h','w24h');names_time<-c('Nut 0h','Nut 1h','Nut 4h','Nut 7h','Nut 10h','Nut 24h','Wash');pal<-c('0h'='#2DAFA0','1h'='#57A9CC','4h'='#4D82C1','7h'='#6F6CB0','10h'='#9A70B8','24h'='#C46A91','w24h'='#E9A042');gain_col<-'#2EAD9F';loss_col<-'#D37B78';sizes<-read.csv(file.path(D,'tad_sizes.csv'));boxes<-read.csv(file.path(D,'box_summary.csv'));counts<-read.csv(file.path(D,'border_counts.csv'));changes<-read.csv(file.path(D,'gain_loss.csv'));boxes$x<-match(boxes$timepoint,times)
# Matplotlib violinplot default: Scott bandwidth,100gridpoints between observed endpoints,per-violin width normalized to its maximum.
kdes<-list();violins<-list();for(i in seq_along(times)){v<-sizes$size_bp[sizes$timepoint==times[i]];h<-sd(v)*length(v)^(-1/5);yy<-seq(min(v),max(v),length.out=100);dd<-vapply(yy,function(y)mean(dnorm((y-v)/h))/h,numeric(1));hw<-.45*dd/max(dd);kdes[[i]]<-data.frame(timepoint=times[i],grid_index=seq_along(yy),position_bp=yy,density=dd,halfwidth=hw,bandwidth_bp=h);violins[[i]]<-data.frame(x=c(i-hw,rev(i+hw)),y=c(yy,rev(yy))/1e6,timepoint=times[i])}
kde<-do.call(rbind,kdes);write.csv(kde,file.path(D,'kde_curves.csv'),row.names=FALSE);violin<-do.call(rbind,violins);boxtext<-paste0('n=',format(boxes$n,big.mark=',',trim=TRUE));br<-do.call(rbind,lapply(2:7,function(i){height<-2.16+(i-2)*.11;data.frame(x=c(1,1,i,i),y=c(height-.025,height,height,height-.025),comparison=i)}));stars<-data.frame(x=(1+2:7)/2,y=2.16+(0:5)*.11+.02,label='*')
base<-theme_classic(base_family='Arial',base_size=7)+theme(axis.text=element_text(size=6,color='#30343B'),axis.title=element_text(size=7,color='#30343B'),axis.line=element_line(color='#59616B',linewidth=.2),axis.ticks=element_line(color='#59616B',linewidth=.2),axis.ticks.length=unit(1,'mm'),plot.margin=margin(3,1,6,2,'mm'),plot.background=element_rect(fill='white',color=NA))
a<-ggplot()+geom_polygon(data=violin,aes(x,y,group=timepoint,color=timepoint),fill=NA,linewidth=.27)+geom_segment(data=boxes,aes(x=x,xend=x,y=whisker_low_bp/1e6,yend=q1_bp/1e6),color='#30343B',linewidth=.22)+geom_segment(data=boxes,aes(x=x,xend=x,y=q3_bp/1e6,yend=whisker_high_bp/1e6),color='#30343B',linewidth=.22)+geom_rect(data=boxes,aes(xmin=x-.15,xmax=x+.15,ymin=q1_bp/1e6,ymax=q3_bp/1e6,fill=timepoint),color='#30343B',linewidth=.35,alpha=.6)+geom_segment(data=boxes,aes(x=x-.15,xend=x+.15,y=median_bp/1e6,yend=median_bp/1e6),color='#30343B',linewidth=.27)+geom_text(data=boxes,aes(x=x,y=2.02,label=boxtext),family='Arial',size=6/ggplot2::.pt,color='#59616B')+geom_path(data=br,aes(x,y,group=comparison),color='#59616B',linewidth=.18)+geom_text(data=stars,aes(x,y,label=label),family='Arial',size=7/ggplot2::.pt,color='#30343B',vjust=0)+scale_fill_manual(values=pal,guide='none')+scale_color_manual(values=pal,guide='none')+scale_x_continuous(breaks=1:7,labels=names_time,limits=c(.4,7.6),expand=c(0,0))+scale_y_continuous(breaks=seq(0,2,.5),labels=sprintf('%.1f',seq(0,2,.5)),limits=c(0,2.88),expand=c(0,0))+labs(x=NULL,y='TAD size (Mb)')+base+theme(axis.text.x=element_text(angle=55,hjust=1,vjust=1,size=6))
# Right panel is designed in common physical coordinate units:label/bar/connector/pie/number lanes cannot drift into one another.
counts$y<-seq(90,18,by=-12);scale_bar<-48/max(counts$total);counts$x0<-13;counts$xmid<-13+counts$invariant*scale_bar;counts$xend<-13+counts$total*scale_bar;counts$label<-names_time;lum<-function(col){v<-as.numeric(col2rgb(col))/255;v<-ifelse(v<=.04045,v/12.92,((v+.055)/1.055)^2.4);sum(v*c(.2126,.7152,.0722))};counts$ink<-ifelse(vapply(pal[times],lum,numeric(1))>.179,'#000000','#FFFFFF');counts$labfill<-vapply(times,function(t){rgb<-col2rgb(pal[t])/255;rgb((1+rgb[1]*.28)/1.28,(1+rgb[2]*.28)/1.28,(1+rgb[3]*.28)/1.28)},character(1));pie<-list();connector<-list();change_text<-list();for(i in 1:6){cy<-mean(counts$y[c(i,i+1)]);frac<-changes$gain_fraction[i];for(j in 1:2){ang<-if(j==1)seq(0,-360*frac,length.out=80)else seq(-360*frac,-360,length.out=80);pie[[length(pie)+1]]<-data.frame(x=c(70,70+2.3*cos(ang*pi/180),70),y=c(cy,cy+2.3*sin(ang*pi/180),cy),id=paste(i,j,sep='-'),fill=if(j==1)gain_col else loss_col)};connector[[i]]<-data.frame(x=c(counts$xend[i],65,65,counts$xend[i+1]),y=c(counts$y[i]-2.7,counts$y[i]-4,counts$y[i+1]+4,counts$y[i+1]+2.7),id=i);change_text[[i]]<-data.frame(x=74,y=c(cy+1.5,cy-1.5),label=c(paste0('+',changes$gain[i]),paste0('-',changes$loss[i])),color=c('#16776D','#AA4C50'))}
pies<-do.call(rbind,pie);paths<-do.call(rbind,connector);ct<-do.call(rbind,change_text);write.csv(pies,file.path(W,'pie-vertices.csv'),row.names=FALSE);write.csv(counts,file.path(W,'bar-layout.csv'),row.names=FALSE)
b<-ggplot()+geom_rect(data=counts,aes(xmin=x0,xmax=xmid,ymin=y-2.1,ymax=y+2.1),fill='#C1C9D1',color='#30343B',linewidth=.2)+geom_rect(data=counts,aes(xmin=xmid,xmax=xend,ymin=y-2.1,ymax=y+2.1,fill=timepoint),color='#30343B',linewidth=.2)+scale_fill_manual(values=pal,guide='none')+geom_text(data=counts,aes(x=(x0+xmid)/2,y=y,label=invariant),family='Arial',size=6/ggplot2::.pt,color='#30343B')+geom_text(data=counts,aes(x=(xmid+xend)/2,y=y,label=variant,color=ink),family='Arial',size=6/ggplot2::.pt)+ggnewscale::new_scale_fill()+geom_rect(data=counts,aes(xmin=0,xmax=11,ymin=y-2.5,ymax=y+2.5,fill=labfill),color='#59616B',linewidth=.15)+scale_fill_identity()+geom_text(data=counts,aes(x=5.5,y=y,label=label),family='Arial',size=6/ggplot2::.pt,color='#30343B')+geom_path(data=paths,aes(x,y,group=id),color='#87909A',linewidth=.18,arrow=arrow(type='closed',length=unit(1.2,'mm')))+geom_polygon(data=pies,aes(x,y,group=id,fill=fill),color='white',linewidth=.12)+geom_text(data=ct,aes(x,y,label=label,color=color),family='Arial',size=6/ggplot2::.pt,hjust=0)+scale_color_identity()+annotate('text',x=37,y=108,label='Number of TAD borders',family='Arial',size=8/ggplot2::.pt,color='#30343B')+annotate('text',x=mean(c(13,counts$xmid[1])),y=99,label='Invariant',family='Arial',size=7/ggplot2::.pt,color='#59616B')+annotate('text',x=mean(c(counts$xmid[1],61)),y=99,label='Variant',family='Arial',size=7/ggplot2::.pt,color='#59616B')+annotate('text',x=74,y=99,label='Gain / loss',family='Arial',size=7/ggplot2::.pt,color='#59616B')+coord_equal(xlim=c(-1,86),ylim=c(8,112),expand=FALSE,clip='off')+theme_void(base_family='Arial')+theme(plot.margin=margin(0,1,0,0,'mm'),plot.background=element_rect(fill='white',color=NA))
ragg::agg_png(file.path(W,'preview.png'),width=183,height=130,units='mm',res=300,background='white');p<-cowplot::ggdraw()+cowplot::draw_plot(a,x=.005,y=.03,width=.48,height=.94)+cowplot::draw_plot(b,x=.51,y=.02,width=.485,height=.96)+cowplot::draw_label('A',x=.01,y=.985,hjust=0,vjust=1,fontfamily='Arial',fontface='bold',size=9,color='#30343B')+cowplot::draw_label('B',x=.515,y=.985,hjust=0,vjust=1,fontfamily='Arial',fontface='bold',size=9,color='#30343B')+theme(plot.background=element_rect(fill='white',color=NA));saveRDS(p,file.path(W,'plot.rds'));print(p);dev.off();capture.output(sessionInfo(),file=file.path(W,'explore-sessionInfo.txt'))
